import 'package:flutter/cupertino.dart';
import 'package:flutter/material.dart';
import '../widgets/glass_card.dart';
class SettingsScreen extends StatelessWidget{const SettingsScreen({super.key});@override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(18),children:[const Text('Settings',style:TextStyle(fontSize:32,fontWeight:FontWeight.w800,letterSpacing:-1)),const SizedBox(height:22),GlassCard(child:Column(children:[_row(CupertinoIcons.shield,'Local Signing','P12 + mobileprovision are processed on-device'),const Divider(height:26),_row(CupertinoIcons.folder,'Signed Output','Export signed IPA files from the Files tab'),const Divider(height:26),_row(CupertinoIcons.lock,'Privacy','Certificates stay inside the app sandbox')])),const SizedBox(height:16),const GlassCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('About Sign',style:TextStyle(fontWeight:FontWeight.w800,fontSize:17)),SizedBox(height:7),Text('A clean Flutter interface with a native iOS signing engine.',style:TextStyle(color:Colors.black54)),SizedBox(height:12),Text('Version 1.0.0',style:TextStyle(color:Colors.black38,fontSize:12))]))]);Widget _row(IconData i,String t,String s)=>Row(children:[Icon(i),const SizedBox(width:13),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(t,style:const TextStyle(fontWeight:FontWeight.w700)),Text(s,style:const TextStyle(color:Colors.black45,fontSize:12))]))]);}
